// The kernel for Android (ADR-0027): keel-ffi built with the NDK through cargo-ndk, for arm64-v8a
// and, for emulators, x86_64; its Kotlin bindings, generated by UniFFI; and the register's
// adapter to them.

import com.android.build.api.variant.LibraryAndroidComponentsExtension
import java.io.File
import javax.inject.Inject

plugins {
    alias(libs.plugins.android.library)
}

/** Runs a command in the repository that writes into [outputDir], which Gradle then compiles. */
abstract class CargoTask : DefaultTask() {
    @get:OutputDirectory
    abstract val outputDir: DirectoryProperty

    /** The command, `{out}` standing for [outputDir]. */
    @get:Input
    abstract val command: ListProperty<String>

    @get:Input
    abstract val environment: MapProperty<String, String>

    @get:Internal
    abstract val repository: DirectoryProperty

    @get:Inject
    abstract val exec: ExecOperations

    @TaskAction
    fun run() {
        val out = outputDir.get().asFile
        out.deleteRecursively()
        out.mkdirs()
        exec.exec {
            workingDir = repository.get().asFile
            environment(this@CargoTask.environment.get())
            commandLine(command.get().map { if (it == "{out}") out.path else it })
        }
    }
}

val repositoryDir: Directory = layout.projectDirectory.dir("../../..")
// The ABIs to build: every one by default; `-PkeelAbis=x86_64` for an emulator alone.
val abis = providers.gradleProperty("keelAbis").getOrElse("arm64-v8a,x86_64").split(",")

android {
    namespace = "dev.keel.android.kernel"
    compileSdk = 37
    ndkVersion = "30.0.16248370"
    defaultConfig {
        minSdk = 28
        consumerProguardFiles("consumer-rules.pro")
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    testOptions {
        // The unit tests run on the host, against the kernel built for it by `bindings`.
        unitTests.all { test ->
            // Cargo's target directory, wherever CARGO_TARGET_DIR puts it, as generate.sh does.
            val target = System.getenv("CARGO_TARGET_DIR")?.let(::File) ?: repositoryDir.dir("target").asFile
            test.systemProperty("jna.library.path", target.resolve("release").path)
            test.dependsOn("bindings")
        }
    }
}

val androidComponents = extensions.getByType<LibraryAndroidComponentsExtension>()

// The kernel, optimized whatever the variant: a debug build of it is many times larger and
// slower, and its own tests run on the host. Cargo rebuilds only what changed.
val nativeLibraries = tasks.register<CargoTask>("nativeLibraries") {
    description = "Builds keel-ffi for Android with cargo-ndk."
    repository.set(repositoryDir)
    outputDir.set(layout.buildDirectory.dir("generated/jniLibs"))
    command.set(
        listOf("cargo", "ndk") + abis.flatMap { listOf("-t", it) } +
            listOf("-P", "28", "-o", "{out}", "build", "-p", "keel-ffi", "--release"),
    )
    environment.set(
        androidComponents.sdkComponents.ndkDirectory.map { mapOf("ANDROID_NDK_HOME" to it.asFile.path) },
    )
    outputs.upToDateWhen { false }
}

// The bindings, generated from the kernel built for the host: the same library, so the same
// Kotlin.
val bindings = tasks.register<CargoTask>("bindings") {
    description = "Generates keel-ffi's Kotlin bindings with UniFFI."
    repository.set(repositoryDir)
    outputDir.set(layout.buildDirectory.dir("generated/uniffi"))
    command.set(listOf("bindings/kotlin/generate.sh", "--release", "--out", "{out}"))
    environment.set(emptyMap())
    outputs.upToDateWhen { false }
}

androidComponents.onVariants { variant ->
    variant.sources.jniLibs?.addGeneratedSourceDirectory(nativeLibraries, CargoTask::outputDir)
    variant.sources.kotlin?.addGeneratedSourceDirectory(bindings, CargoTask::outputDir)
}

dependencies {
    api(project(":register"))
    implementation(libs.kotlinx.coroutines.core)
    // JNA's Android archive, with its native dispatch library for each ABI.
    implementation(libs.jna) { artifact { type = "aar" } }

    // The host's JNA, for the unit tests against the kernel built for the host.
    testImplementation(libs.jna)
    testImplementation(libs.junit)
    testImplementation(libs.kotlin.test.junit)
}
